DO $patch$ DECLARE s text; BEGIN SELECT pg_get_functiondef('public.mcp_mutation_availability()'::regprocedure) INTO s; IF strpos(s,'(''add_note'',''public.append_work_item_note(uuid,text)'')')=0 THEN RAISE EXCEPTION 'availability anchor mismatch'; END IF; s:=replace(s,'(''add_note'',''public.append_work_item_note(uuid,text)'')','(''correct_hearing'',''public.mcp_correct_hearing(uuid,jsonb,timestamptz,text,text)''), (''reclassify_work_item'',''public.mcp_reclassify_work_item(uuid,text,text,timestamptz,text,text)''), (''add_note'',''public.append_work_item_note(uuid,text)'')'); EXECUTE s; END $patch$;